'use strict';
// 独立原型：不读取 .env，不调用网络 API，不写入 data/。
const $ = id => document.getElementById(id);
const names = ['键盘','鼓','吉他','贝斯'];
const colors = ['#7eaa74','#ce9b6d','#859fbb','#b199ba'];
const presets = [['柔和键盘','明亮键盘'],['轻鼓组','电子鼓'],['拨弦吉他','柔和吉他'],['圆润贝斯','明亮贝斯']];
const keyMap = {KeyA:60,KeyW:61,KeyS:62,KeyE:63,KeyD:64,KeyF:65,KeyT:66,KeyG:67,KeyY:68,KeyH:69,KeyU:70,KeyJ:71,KeyK:72};
const keyLabels = ['A','W','S','E','D','F','T','G','Y','H','U','J','K'];
const STORE = 'shiyin-html-prototype-v1';
let instrument=0,trackIndex=0,selected=null,recording=false,recordStart=0,context=null,playing=false,playStart=0,playTimer=null,playEvents=[],replayTimers=[],generationTimer=null,generating=false,toastTimer;
const voices=new Map();
const clone = value => JSON.parse(JSON.stringify(value));
const id = () => 'p'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
function score(){return names.map((name,t)=>({name,mute:false,solo:false,volume:70,timbre:0,notes:Array.from({length:t===1?16:8},(_,i)=>({id:id(),pitch:t===1?60+(i%2)*4:60+[0,4,7,4,2,5,9,7][i],start:t===1?i:i*2,duration:t===1?.5:1.5}))}));}
function project(name){return {id:id(),name,theme:'毕业后，奔向各自的生活',emotion:'有一点不舍，但希望明亮、轻快，像带着期待走向远方。',lyrics:'',selectedLines:[],mode:'extend',recorded:[],tracks:score(),revision:1,approved:null,history:[{label:'载入预设四声部示例（非 AI 生成）',time:new Date().toLocaleTimeString()}],undo:[],redo:[]};}
let projects=[project('写给明天的歌')],currentId=projects[0].id;
try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved?.version===1&&Array.isArray(saved.projects)&&saved.projects.length&&saved.projects.every(p=>p.id&&typeof p.name==='string'&&Array.isArray(p.tracks)&&p.tracks.length===4&&p.tracks.every(t=>Array.isArray(t.notes))&&Array.isArray(p.history)&&Array.isArray(p.recorded))){projects=saved.projects;currentId=projects.some(p=>p.id===saved.currentId)?saved.currentId:projects[0].id;projects.forEach(p=>{p.undo=[];p.redo=[];});}}catch{ /* 损坏或受限存储不阻止页面打开。 */ }
const current=()=>projects.find(p=>p.id===currentId);
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
function dirty(){ $('save-status').textContent='有未保存的演示修改'; }
function history(label){current().history.unshift({label,time:new Date().toLocaleTimeString()});current().history=current().history.slice(0,80);dirty();}
function invalidate(){current().approved=null;document.querySelectorAll('.review-check').forEach(c=>c.checked=false);renderReview();dirty();}
function snapshot(){return clone({tracks:current().tracks,revision:current().revision});}
function edit(label,action){stopPlayback();current().undo.push(snapshot());current().undo=current().undo.slice(-40);current().redo=[];action();current().revision++;invalidate();history(label);renderEditor();}
function modal(title,body){$('modal-title').textContent=title;$('modal-body').replaceChildren();if(typeof body==='string'){const p=document.createElement('p');p.textContent=body;$('modal-body').append(p);}else $('modal-body').append(body);$('modal').showModal();}
$('close-modal').onclick=()=>$('modal').close();
$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
function show(view){finishRecording();stopPlayback();document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!=='view-'+view);document.querySelectorAll('.steps button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='edit')renderEditor();if(view==='review')renderReview();window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));
function renderProjects(){ $('projects').replaceChildren();projects.forEach(p=>{const button=document.createElement('button');button.className='project-item'+(p.id===currentId?' active':'');button.textContent='♫  '+p.name;const small=document.createElement('small');small.textContent='原型工程 · 示例数据';button.append(small);button.onclick=()=>{if(generating)return toast('请先取消当前生成演示，再切换歌曲。');finishRecording();stopPlayback();currentId=p.id;selected=null;renderAll();show('create');dirty();};$('projects').append(button);});$('project-title').textContent=current().name;}
$('new-project').onclick=()=>{if(generating)return toast('请先取消生成演示。');const form=document.createElement('form');const label=document.createElement('label');label.className='field';label.textContent='歌曲名称';const input=document.createElement('input');input.required=true;input.maxLength=40;input.placeholder='例如：周末的小旅行';label.append(input);const note=document.createElement('p');note.className='muted';note.textContent='只创建浏览器中的原型工程，不创建 data/ 文件夹。';const submit=document.createElement('button');submit.className='primary';submit.textContent='创建演示工程';form.append(label,note,submit);form.onsubmit=e=>{e.preventDefault();if(!input.value.trim())return;finishRecording();stopPlayback();const p=project(input.value.trim());p.theme='';p.emotion='';projects.push(p);currentId=p.id;selected=null;$('modal').close();renderAll();show('create');dirty();};modal('新建一首歌',form);input.focus();};
$('save').onclick=()=>{if(recording)finishRecording();try{localStorage.setItem(STORE,JSON.stringify({version:1,currentId,projects:projects.map(p=>({...p,undo:[],redo:[]}))}));$('save-status').textContent='已保存到当前浏览器';toast('已保存原型状态。没有写入 data/，也未生成 MIDI 或 MP3。');}catch{toast('浏览器存储不可用或空间不足，请下载原型状态 JSON。');}};
$('about').onclick=()=>modal('这是可以操作的设计原型','真实可用：歌曲切换、简易合成音、音符录制回放、TXT 读取与连续选行、示例音符编辑、试听控制、撤销重做、审核状态、浏览器保存与 JSON 下载。模拟：AI 生成、自然语言理解、MIDI 导入、MIDI/MP3 导出、全曲生成。所有示例不保证音乐质量或歌词可唱性。浏览器保存不写入 data/；换浏览器、地址或清理缓存后不会自动共享或保留。');
$('history-open').onclick=()=>{const container=document.createElement('div');const note=document.createElement('p');note.textContent='操作记录保存在本工程。撤销/重做只覆盖本次打开后的编曲编辑；历史记录本身不会被撤销。';note.className='muted';container.append(note);current().history.forEach(h=>{const row=document.createElement('div');row.className='history-row';row.textContent=h.label;const small=document.createElement('small');small.textContent=h.time;row.append(small);container.append(row);});modal('修改历史 · '+current().name,container);};
function renderInputs(){const p=current();$('theme').value=p.theme;$('emotion').value=p.emotion;$('lyrics').value=p.lyrics;$('melody-mode').value=p.mode;renderLyrics();renderRecord();}
for(const [input,field] of [['theme','theme'],['emotion','emotion'],['melody-mode','mode']])$(input).addEventListener('input',()=>{current()[field]=$(input).value;invalidate();});
document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{$('emotion').value=b.dataset.mood;current().emotion=b.dataset.mood;invalidate();});
$('lyrics').oninput=()=>{current().lyrics=$('lyrics').value;current().selectedLines=[];invalidate();renderLyrics();};
$('sample-lyrics').onclick=()=>{current().lyrics='把昨天装进行囊\n沿着晨光去远方\n就算挥手时红了眼眶\n也要笑着奔向下一场';current().selectedLines=[0,1];$('lyrics').value=current().lyrics;invalidate();renderLyrics();};
$('lyrics-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const pid=currentId;if(!file.name.toLowerCase().endsWith('.txt')||file.size>512000){e.target.value='';return toast('请选择不超过 500 KB 的 TXT 文件。');}try{const text=await file.text();if(pid!==currentId)return;if(text.includes('\uFFFD'))return toast('文件可能不是 UTF-8 编码，请转为 UTF-8 后再上传。');current().lyrics=text.replace(/\r\n?/g,'\n');current().selectedLines=[];$('lyrics').value=current().lyrics;invalidate();renderLyrics();toast('已读取歌词，请勾选用于短曲的连续几行。');}catch{toast('读取失败，请重试或直接粘贴歌词。');}finally{e.target.value='';}};
function renderLyrics(){const p=current();$('lyric-lines').replaceChildren();p.lyrics.split('\n').forEach((line,i)=>{if(!line.trim())return;const label=document.createElement('label');const check=document.createElement('input');check.type='checkbox';check.checked=p.selectedLines.includes(i);check.onchange=()=>{if(check.checked){const indices=[...p.selectedLines,i];const lo=Math.min(...indices),hi=Math.max(...indices);p.selectedLines=p.lyrics.split('\n').map((s,n)=>s.trim()&&n>=lo&&n<=hi?n:-1).filter(n=>n>=0);}else{p.selectedLines=p.selectedLines.filter(n=>n<i);}invalidate();renderLyrics();};label.append(check,document.createTextNode(line));$('lyric-lines').append(label);});$('lyric-count').textContent=p.selectedLines.length?'已选 '+p.selectedLines.length+' 行 · 连续选段':'尚未选择歌词';}
names.forEach((name,i)=>{const b=document.createElement('button');b.textContent=['♬ ','◉ ','♧ ','≋ '][i]+name;b.dataset.instrument=i;b.onclick=()=>{releaseAll();instrument=i;renderInstruments();};$('instruments').append(b);});
function renderInstruments(){document.querySelectorAll('[data-instrument]').forEach(b=>b.classList.toggle('active',+b.dataset.instrument===instrument));}
const whiteNotes=[60,62,64,65,67,69,71,72],blackPositions={61:1,63:2,66:4,68:5,70:6};
whiteNotes.concat(Object.keys(blackPositions).map(Number)).forEach(pitch=>{const b=document.createElement('button');b.className='key'+(blackPositions[pitch]?' black':'');b.dataset.pitch=pitch;b.setAttribute('aria-label','演奏 '+pitch+'，按键 '+keyLabels[pitch-60]);const span=document.createElement('span');span.textContent=keyLabels[pitch-60];b.append(span);if(blackPositions[pitch])b.style.left=`calc(${blackPositions[pitch]*12.5}% - 2.8%)`;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);noteOn('pointer'+e.pointerId,pitch);};b.onpointerup=e=>noteOff('pointer'+e.pointerId);b.onpointercancel=e=>noteOff('pointer'+e.pointerId);$('keyboard').append(b);});
function audio(){if(!context){const Constructor=window.AudioContext||window.webkitAudioContext;if(!Constructor)throw Error('Audio unavailable');context=new Constructor();}if(context.state==='suspended')context.resume().catch(()=>toast('音频尚未启用，请再次点击琴键。'));return context;}
function synth(pitch,t=instrument,volume=.15,timbre=0){if(volume<=0)return ()=>{};try{const ctx=audio(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=t===0?(timbre?'sine':'triangle'):t===1?(timbre?'sawtooth':'square'):t===2?(timbre?'triangle':'sawtooth'):(timbre?'triangle':'sine');osc.frequency.value=t===1?(pitch>62?160:75)*(timbre?1.5:1):440*2**((pitch-69-(t===3?24:0))/12);gain.gain.setValueAtTime(0,ctx.currentTime);gain.gain.linearRampToValueAtTime(volume*(t===1?.3:1),ctx.currentTime+.012);if(t===1)gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.13);osc.connect(gain).connect(ctx.destination);osc.start();let ended=false;return ()=>{if(ended)return;ended=true;gain.gain.cancelScheduledValues(ctx.currentTime);gain.gain.setTargetAtTime(.0001,ctx.currentTime,.025);osc.stop(ctx.currentTime+.15);};}catch{toast('当前浏览器无法启用音频；其他原型操作仍可使用。');return ()=>{};}}
function noteOn(token,pitch){if(voices.has(token))return;const voice={pitch,stop:synth(pitch),time:performance.now(),track:instrument};voices.set(token,voice);document.querySelectorAll(`[data-pitch="${pitch}"]`).forEach(b=>b.classList.add('pressed'));}
function noteOff(token){const v=voices.get(token);if(!v)return;v.stop();voices.delete(token);if(recording&&v.time>=recordStart){current().recorded.push({pitch:v.pitch,start:(v.time-recordStart)/1000,duration:Math.max(.06,(performance.now()-v.time)/1000),track:v.track});dirty();renderRecord();}if(![...voices.values()].some(x=>x.pitch===v.pitch))document.querySelectorAll(`[data-pitch="${v.pitch}"]`).forEach(b=>b.classList.remove('pressed'));}
function releaseAll(){[...voices.keys()].forEach(noteOff);}
window.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||$('modal').open||$('view-create').hidden||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(keyMap[e.code]){e.preventDefault();noteOn(e.code,keyMap[e.code]);}});
window.addEventListener('keyup',e=>noteOff(e.code));
window.addEventListener('blur',()=>{finishRecording();releaseAll();stopPlayback();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){finishRecording();releaseAll();stopPlayback();}});
$('record').onclick=()=>{if(recording)return finishRecording();stopPlayback();releaseAll();current().recorded=[];recordStart=performance.now();recording=true;invalidate();renderRecord();toast('正在录制。点击琴键或使用 A–K，完成后点击停止。');};
function finishRecording(){if(!recording)return;releaseAll();recording=false;history('录制片段：'+current().recorded.length+' 个音符');renderRecord();}
function renderRecord(){$('record').innerHTML=recording?'<span>■</span> 停止录制':'<span>●</span> 开始录制';$('record').classList.toggle('recording',recording);$('record-info').textContent=recording?'录制中 · '+current().recorded.length+' 个音符':current().recorded.length?current().recorded.length+' 个音符 · 可回放':'还没有录制片段';}
$('clear-record').onclick=()=>{finishRecording();stopPlayback();current().recorded=[];invalidate();renderRecord();};
$('replay').onclick=()=>{finishRecording();stopPlayback();if(!current().recorded.length)return toast('先录制几个音符，再回放。');audio();for(const n of current().recorded){replayTimers.push(setTimeout(()=>{const stop=synth(n.pitch,n.track);replayTimers.push(setTimeout(stop,n.duration*1000));replayStops.push(stop);},n.start*1000));}toast('回放已录制的简易合成音片段。');};
let replayStops=[];
$('generate').onclick=()=>{if(generating)return;finishRecording();const p=current();if(!p.theme.trim()&&!p.emotion.trim()&&!p.selectedLines.length&&!p.recorded.length)return toast('请先写一点主题、感受，选择歌词或录制片段。');if(p.lyrics.trim()&&!p.selectedLines.length)return toast('已有歌词，请先勾选要使用的连续几行。');stopPlayback();generating=true;const pid=currentId,fail=$('demo-result').value==='failure';let phase=0;$('generate').disabled=true;$('generation-progress').hidden=false;$('generation-progress').value=0;$('cancel-generation').hidden=false;const stages=['整理输入 · 模拟','规划共同段落与四声部 · 模拟','加载预设音符 · 非 AI 生成','准备示例编辑界面'];$('generation-status').textContent=stages[0];generationTimer=setInterval(()=>{phase++;$('generation-progress').value=phase;if(phase<4){$('generation-status').textContent=stages[phase];return;}cancelGeneration(false);if(pid!==currentId)return;if(fail){$('generation-status').textContent='模拟失败：未修改已有作品，可再次体验。';return toast('模拟请求失败，输入与原作品已保留。');}edit('演示生成：加载预设四声部，与输入内容无音乐对应',()=>{p.tracks=score();});$('generation-status').textContent='预设示例已加载；并非根据输入生成。';show('edit');toast('已加载预设示例。歌词、主题与旋律未参与实际生成。');},650);};
function cancelGeneration(notify=true){clearInterval(generationTimer);generating=false;$('generate').disabled=false;$('cancel-generation').hidden=true;if(notify){$('generation-status').textContent='已取消演示，原作品保留。';$('generation-progress').hidden=true;}}
$('cancel-generation').onclick=()=>cancelGeneration();
$('open-example').onclick=()=>show('edit');
function renderEditor(){const p=current();$('tracks').replaceChildren();p.tracks.forEach((track,i)=>{const row=document.createElement('div');row.className='track'+(trackIndex===i?' active':'');row.style.setProperty('--track-color',colors[i]);const choose=document.createElement('button');choose.className='track-select';choose.textContent=track.name+'　'+(i===0?'旋律':i===1?'节奏':i===2?'和声':'低音');choose.onclick=()=>{trackIndex=i;selected=null;renderEditor();};const timbre=document.createElement('select');timbre.setAttribute('aria-label',track.name+'音色');presets[i].forEach((name,j)=>{const option=new Option(name+'（合成示意）',j);timbre.add(option);});timbre.value=track.timbre;timbre.onchange=()=>edit('调整'+track.name+'音色',()=>track.timbre=+timbre.value);const controls=document.createElement('div');controls.className='track-controls';for(const [key,label] of [['solo','独奏'],['mute','静音']]){const b=document.createElement('button');b.textContent=label;b.className=track[key]?'on':'';b.setAttribute('aria-pressed',track[key]);b.onclick=()=>edit(label+track.name,()=>track[key]=!track[key]);controls.append(b);}const volume=document.createElement('input');volume.type='range';volume.min=0;volume.max=100;volume.value=track.volume;volume.setAttribute('aria-label',track.name+'音量');volume.onchange=()=>edit('调整'+track.name+'音量',()=>track.volume=+volume.value);controls.append(volume);row.append(choose,timbre,controls);$('tracks').append(row);});$('track-title').textContent=names[trackIndex]+' · 音符编辑';$('undo').disabled=!p.undo.length;$('redo').disabled=!p.redo.length;renderRoll();}
const svgNS='http://www.w3.org/2000/svg';
function svgEl(tag,attrs){const el=document.createElementNS(svgNS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el;}
function renderRoll(){const svg=$('roll'),track=current().tracks[trackIndex];svg.replaceChildren();for(let i=0;i<=16;i++)svg.append(svgEl('line',{x1:i*50,y1:0,x2:i*50,y2:240,stroke:i%4?'#e5eadd':'#cad4bf'}));for(let i=0;i<12;i++){svg.append(svgEl('line',{x1:0,y1:i*20,x2:800,y2:i*20,stroke:'#e5eadd'}));}track.notes.forEach(n=>{const rect=svgEl('rect',{x:n.start*50+2,y:(71-n.pitch)*20+3,width:Math.max(5,n.duration*50-4),height:14,rx:4,fill:colors[trackIndex],stroke:selected===n.id?'#244733':'none','stroke-width':3,tabindex:0,role:'button','aria-label':`音符 ${n.pitch}，第 ${n.start} 拍，长度 ${n.duration} 拍`});rect.style.cursor='pointer';const select=()=>{selected=n.id;renderRoll();};rect.onclick=e=>{e.stopPropagation();select();};rect.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};svg.append(rect);});const n=track.notes.find(n=>n.id===selected);$('note-pitch').value=n?.pitch??60;$('note-start').value=n?.start??0;$('note-duration').value=n?.duration??1;for(const control of ['note-pitch','note-start','note-duration','apply-note','delete-note'])$(control).disabled=!n;$('note-help').textContent=n?'已选择音符；修改后点击“应用修改”。':'点网格添加，或选择已有音符。';}
for(let p=60;p<=71;p++)$('note-pitch').add(new Option(['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][p-60]+'4 · '+p,p));
$('roll').onclick=e=>{const box=$('roll').getBoundingClientRect();const start=Math.min(15.5,Math.max(0,Math.floor((e.clientX-box.left)/box.width*32)/2));const pitch=71-Math.min(11,Math.max(0,Math.floor((e.clientY-box.top)/box.height*12)));const n={id:id(),pitch,start,duration:Math.min(1,16-start)};edit('添加'+names[trackIndex]+'音符',()=>{current().tracks[trackIndex].notes.push(n);selected=n.id;});};
$('apply-note').onclick=()=>{const start=+$('note-start').value,duration=+$('note-duration').value,pitch=+$('note-pitch').value;if(!Number.isFinite(start)||!Number.isFinite(duration)||start<0||duration<.5||start+duration>16)return toast('音符应在前 16 拍内，时长至少 0.5 拍。');edit('调整音符位置、音高或时长',()=>{Object.assign(current().tracks[trackIndex].notes.find(n=>n.id===selected),{start,duration,pitch});});};
$('delete-note').onclick=()=>edit('删除音符',()=>{current().tracks[trackIndex].notes=current().tracks[trackIndex].notes.filter(n=>n.id!==selected);selected=null;});
for(const [button,from,to,label] of [['undo','undo','redo','撤销'],['redo','redo','undo','重做']])$(button).onclick=()=>{const p=current();if(!p[from].length)return;stopPlayback();p[to].push(snapshot());const s=p[from].pop();p.tracks=s.tracks;p.revision++;selected=null;invalidate();history(label+'一次编曲编辑');renderEditor();};
$('modify').onclick=()=>{const instruction=$('instruction').value.trim();if(!instruction)return toast('请先输入一句整曲修改要求。');edit('自然语言修改演示：'+instruction,()=>{current().tracks.forEach(t=>t.notes.forEach(n=>n.duration=Math.max(.5,n.duration*.8)));});toast('已执行预设修改：全部声部音符缩短 20%（最短 0.5 拍），未理解指令。');};
$('midi-demo').onclick=()=>modal('MIDI 导入 · 流程示例','正式版本会解析上传 MIDI 的音符、速度、通道与乐器。本原型未实现 MIDI 解析，不能将外部文件当作已导入；当前仍使用预设四声部示例。');
function stopPlayback(){clearInterval(playTimer);playing=false;playEvents=[];replayTimers.forEach(clearTimeout);replayTimers=[];replayStops.forEach(stop=>stop());replayStops=[];$('play').textContent='▶ 试听示例';$('play-time').textContent='00:00 / 01:00';}
$('stop').onclick=stopPlayback;
$('play').onclick=()=>{if(playing)return stopPlayback();finishRecording();stopPlayback();audio();const p=current(),solo=p.tracks.some(t=>t.solo);for(let block=0;block<8;block++)p.tracks.forEach((t,i)=>{if(t.mute||(solo&&!t.solo))return;t.notes.forEach(n=>{const start=block*8+n.start*.5;if(start<60)playEvents.push({start,duration:Math.min(n.duration*.5,60-start),pitch:n.pitch,track:i,volume:t.volume/100*.11,timbre:t.timbre});});});playEvents.sort((a,b)=>a.start-b.start);playing=true;playStart=performance.now();$('play').textContent='■ 停止试听';toast('试听将循环前 4 小节至 60 秒；这是合成音示例，不是完整编曲。');playTimer=setInterval(()=>{const elapsed=(performance.now()-playStart)/1000;$('play-time').textContent='00:'+String(Math.min(59,Math.floor(elapsed))).padStart(2,'0')+' / 01:00';while(playEvents.length&&playEvents[0].start<=elapsed){const n=playEvents.shift(),stop=synth(n.pitch,n.track,n.volume,n.timbre);replayStops.push(stop);replayTimers.push(setTimeout(stop,n.duration*1000));}if(elapsed>=60)stopPlayback();},25);};
function renderReview(){const p=current();$('revision-label').textContent='示例版本 v'+p.revision;$('approval-status').textContent=p.approved===p.revision?'当前版本已标记通过（仅流程演示）。':'当前版本尚未审核。';$('full-song').disabled=p.approved!==p.revision;}
$('approve').onclick=()=>{if(![...document.querySelectorAll('.review-check')].every(c=>c.checked))return toast('请先完成三项审核勾选。');current().approved=current().revision;history('标记 v'+current().revision+' 审核通过（演示）');renderReview();};
$('full-song').onclick=()=>modal('全曲生成 · 后续阶段','当前仅演示审核门槛。正式版本仍需要用户明确发起全曲生成；此按钮不会调用模型或生成音乐。');
document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>modal(b.dataset.export+' 导出 · 流程演示',b.dataset.export==='MIDI'?'正式版本将导出各声部音符、轨道名称和实际乐器信息，并保留鼓的打击乐语义。当前未生成或下载 MIDI 文件。':'正式版本将使用 FluidSynth 和音色库渲染，再由 FFmpeg 编码。当前没有渲染音频，也没有生成或下载 MP3。'));
$('download-json').onclick=()=>{const p=current();const content={prototype:true,notice:'页面原型状态；不是正式歌曲工程，不含真实 AI 编曲或歌词对齐结果。',project:{...p,undo:[],redo:[]}};const url=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='shiyin-prototype-'+p.name.replace(/[<>:"/\\|?*]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下载原型状态 JSON；不是 MIDI 或 MP3。');};
function renderAll(){renderProjects();renderInputs();renderInstruments();renderEditor();document.querySelectorAll('.review-check').forEach(c=>c.checked=false);renderReview();}
renderAll();
